text:
    case "href":
    case "getetag":
      this.tag = aLocalName.replace(/-/g, "");
      this.currentResponse[this.tag] = "";
      break;
  }
  this.logXML += "<" + aQName + ">";
}

async endElement(aUri, aLocalName, aQName) {
  switch (aLocalName) {
    case "response": {
      const resp = this.currentResponse;
      if (resp.href && resp.href.length) {
        resp.href = this.calendar.ensureDecodedPath(resp.href);
      }
      if (
        resp.href &&
        resp.href.length &&
        resp.status &&
        resp.status.length &&
        resp.status.indexOf(" 404") > 0
      ) {
        if (this.calendar.mHrefIndex[resp.href]) {
          try {
            await this.calendar.deleteTargetCalendarItem(resp.href);
          } catch (ex) {
            // Don't let an exception here prevent us continuing.
            lazy.log.error(`Delete item FAILED; path=${resp.href}`, ex);
          }
        } else {
          lazy.log.debug("CalDAV: skipping unfound deleted item : " + resp.href);
        }
        // Created or Updated item
      } else if (
        resp.getetag &&
        resp.getetag.length &&
        resp.href &&
        resp.href.length &&
        resp.calendardata &&
        resp.calendardata.length
      ) {
        let oldEtag;
        const itemId = this.calendar.mHrefIndex[resp.href];
        if (itemId) {
          oldEtag = this.calendar.mItemInfoCache[itemId].etag;
        } else {
          oldEtag = null;
        }
        if (!oldEtag || oldEtag != resp.getetag || this.listener) {
          try {
            await this.calendar.addTargetCalendarItem(
              resp.href,
              resp.calendardata,
              this.baseUri,
              resp.getetag,
              this.listener
            );
          } catch (ex) {
            // Don't let an exception here prevent us continuing.
            lazy.log.error(`Add item FAILED; path=${resp.href}`, ex);
          }

          // Every 10 items yield the event loop. Otherwise, we could end up parsing every
          // item and adding them all to the calendar without stopping, which makes the UI
          // appear unresponsive. This is especially bad for calendars without offline
          // storage, as they get updated immediately on start-up, and would delay how soon
          // the user can start doing things.
          if (++this.shouldYieldEventLoop == 10) {
            await new Promise(resolve => setTimeout(resolve));
            this.shouldYieldEventLoop = 0;
          }
        } else {
          lazy.log.debug("CalDAV: skipping item with unmodified etag : " + oldEtag);
        }
      } else {
        lazy.log.warn(
          "CalDAV: Unexpected response, status: " +
            resp.status +
            ", href: " +
            resp.href +
            " calendar-data:\n" +
            resp.calendardata
        );
        this.unhandledErrors++;
      }
      break;
    }
    case "propstat": {
      this.isInPropStat = false;
      break;
    }
  }
  this.tag = null;
  this.logXML += "</" + aQName + ">";
}

